catalog_script_client.script:
function onLoad() {
    // Hide the entire right-hand column (Order this Item, Quantity, Cart, Delivery time)
    // Note: Class names can vary slightly depending on your instance version (e.g., standard ESC portal vs. Service Portal)
    try {
        var rightColumn = document.querySelectorAll('.sc-sticky-item-sidebar, .col-sm-4.ng-scope');
        for (var i = 0; i < rightColumn.length; i++) {
            // Check if it contains the order/cart elements to avoid hiding wrong columns
            if (rightColumn[i].innerHTML.indexOf('Order Now') > -1) {
                rightColumn[i].style.display = 'none';
            }
        }

        // Alternatively, target specific wrapper elements if needed:
        // g_form.$private.options.showPrices = false; // if hiding prices helps clean up
    } catch(e) {
        console.log(e);
    }
}
